  [16914] = { "Genera una violenta tempesta nell'area bersaglio che infligge $N1 danni da natura ai nemici ogni $D1 e aumenta l'intervallo tra gli attacchi dei nemici del $N3%. Dura $D2. Il Druido deve mantenere la canalizzazione affinché l'incantesimo resti attivo.", "$N1 danni ogni $N2 s e intervallo tra gli attacchi aumentato del $N3%.", 0xa16531e4, 0x611b70c0, "uu" },
