  [16918] = { "Aumenta i danni inflitti da ⟦Entangling Roots=Radici Avvolgenti⟧ del $N1% e le sue vittime possono subire fino al $N2% di danni in più senza interrompere l'effetto.", nil, 0x454d0e9d, nil, "um" },
