  [16927] = { "Riduce la velocità di movimento del bersaglio del $N1% e aumenta l'intervallo tra i suoi attacchi del $N2% per $D1.", "Velocità di movimento ridotta del $N1% e intervallo tra gli attacchi aumentato del $N2%.", 0xa2142d05, 0xa4001412, "uu" },
  [16928] = { "Riduce l'armatura di un nemico di $N1. Si accumula fino a 3 volte.", "Armatura ridotta di $N1.", 0x81252116, 0xaede5a15, "uu" },
  [16929] = { "In ⟦Bear Form=Forma d'Orso⟧, ⟦Cat Form=Forma Felina⟧, Dire Bear Form o ⟦Moonkin Form=Forma di Lunagufo⟧ ottieni $N1 punti di Armatura base aggiuntivi per livello e altri $N2 punti di Armatura base per ogni punto di abilità in difesa oltre cinque volte il tuo livello. Questo valore può essere ulteriormente aumentato dai moltiplicatori di tali forme.", nil, 0x36993fb0, nil, "um" },
  [16934] = { "Riduce il costo di Zampata, Morso Primordiale, Spazzata, Sfregio e Graffio di $N1 rabbia o energia.", nil, 0xe6a9fdc1, nil, "um" },
