  [16947] = { "Aumenta i danni inflitti da Spazzata del $N1% e riduce la probabilità che i nemici ti individuino durante il Movimento Furtivo, come se il tuo livello fosse superiore di $N2 livelli.", nil, 0x4568f84c, nil, "um" },
  [16958] = { "Conferisce una probabilità del $N1% di ottenere $N2 rabbia aggiuntiva ogni volta che metti a segno un colpo critico in ⟦Bear Form=Forma d'Orso⟧ o Dire Bear Form. Inoltre, i tuoi colpi critici non periodici delle abilità della ⟦Cat Form=Forma Felina⟧ che generano punti combo hanno una probabilità del $N3% di aggiungere un ulteriore punto combo.", nil, 0xcac757d6, nil, "um" },
